"""Graph ignore rules matched by node title or widget name."""

from __future__ import annotations

import re


class WyslIgnoreRules:
    CATEGORY = "Wysl/工具"
    FUNCTION = "describe"
    RETURN_TYPES = ("STRING",)
    RETURN_NAMES = ("规则",)
    OUTPUT_NODE = True
    DESCRIPTION = "按节点名或选框名忽略多个节点。规则可以是完整名称，也可以是正则，例如 ^图像。"

    @classmethod
    def INPUT_TYPES(cls):
        return {
            "required": {
                "名称": ("STRING", {"default": "忽略所有图像", "multiline": False}),
                "启用": ("BOOLEAN", {"default": False, "label_on": "启用", "label_off": "关闭"}),
                "规则": ("STRING", {
                    "default": "^图像",
                    "multiline": True,
                    "tooltip": "每行一条。普通文字按名称包含匹配；含正则符号时按正则匹配节点标题、类型名和选框名。",
                }),
            }
        }

    @staticmethod
    def describe(名称, 启用, 规则):
        state = "启用" if 启用 else "关闭"
        return (f"{名称} [{state}]\n{规则}",)


def rule_matches(rule, value):
    text = str(value or "")
    pattern = str(rule or "").strip()
    if not pattern or not text:
        return False
    if re.search(r"[\\^$.*+?()[\]{}|]", pattern):
        try:
            return re.search(pattern, text) is not None
        except re.error:
            return False
    return pattern in text


NODE_CLASS_MAPPINGS = {"WyslIgnoreRules": WyslIgnoreRules}
NODE_DISPLAY_NAME_MAPPINGS = {"WyslIgnoreRules": "Wysl-忽略规则"}
